1: /**
2:  * Doc types in fragments. Three lines in five seconds are one turn, not three,
3:  * and answering each separately is what makes a bot feel like a form handler.
4:  *
5:  * Fragments are merged rather than dropped: a dropped line never reaches the
6:  * agent at all, so it never reaches memory either.
7:  *
8:  * Quiet window: wait ~1500ms after the last fragment before draining, with a
9:  * 5s hard cap from the first fragment so a never-ending drip still drains.
10:  */
11: 
12: const DEFAULT_QUIET_MS = 1500;
13: const DEFAULT_HARD_CAP_MS = 5000;
14: 
15: export class TurnBuffer<F, T> {
16:   private readonly buffers = new Map<
17:     string,
18:     { fragments: F[]; target: T; openedAt: number }
19:   >();
20:   private readonly timers = new Map<string, ReturnType<typeof setTimeout>>();
21: 
22:   constructor(
23:     private readonly onReady: (channelId: string) => void,
24:     private readonly quietMs = DEFAULT_QUIET_MS,
25:     private readonly hardCapMs = DEFAULT_HARD_CAP_MS,
26:   ) {}
27: 
28:   /** True when nothing was waiting yet (first fragment of a new turn). */
29:   push(channelId: string, fragment: F, target: T): boolean {
30:     const existing = this.buffers.get(channelId);
31:     if (existing) {
32:       existing.fragments.push(fragment);
33:       existing.target = target;
34:       this.schedule(channelId);
35:       return false;
36:     }
37:     this.buffers.set(channelId, {
38:       fragments: [fragment],
39:       target,
40:       openedAt: Date.now(),
41:     });
42:     this.schedule(channelId);
43:     return true;
44:   }
45: 
46:   take(channelId: string): { fragments: F[]; target: T } | null {
47:     this.clearTimer(channelId);
48:     const buffered = this.buffers.get(channelId);
49:     if (!buffered) return null;
50:     this.buffers.delete(channelId);
51:     return { fragments: buffered.fragments, target: buffered.target };
52:   }
53: 
54:   /** Test helper: force the quiet timer to fire now. */
55:   flushForTest(channelId: string): void {
56:     this.clearTimer(channelId);
57:     if (this.buffers.has(channelId)) this.onReady(channelId);
58:   }
59: 
60:   private schedule(channelId: string): void {
61:     this.clearTimer(channelId);
62:     const buf = this.buffers.get(channelId);
63:     if (!buf) return;
64:     const elapsed = Date.now() - buf.openedAt;
65:     const remainingCap = Math.max(0, this.hardCapMs - elapsed);
66:     const delay = Math.min(this.quietMs, remainingCap);
67:     this.timers.set(
68:       channelId,
69:       setTimeout(() => {
70:         this.timers.delete(channelId);
71:         if (this.buffers.has(channelId)) this.onReady(channelId);
72:       }, delay),
73:     );
74:   }
75: 
76:   private clearTimer(channelId: string): void {
77:     const t = this.timers.get(channelId);
78:     if (t) {
79:       clearTimeout(t);
80:       this.timers.delete(channelId);
81:     }
82:   }
83: }
